/bin/bash -c "python3 - <<'PY'
# Trace the hexadecimal type-selection conditions printed in Figure 24.
for s in ['0x80000000','0x7FFFFFFF','0x8000000000000000']:
    pfxLen=2
    foundFirstNonZero=False
    leadingZeroCount=0
    significantHexDigits=0
    for i in range(pfxLen,len(s)):
        currentChar=s[i]
        if not foundFirstNonZero and currentChar=='0':
            leadingZeroCount+=1
        elif not foundFirstNonZero and currentChar"'!='"'0':
            foundFirstNonZero=True
        if foundFirstNonZero:
            significantHexDigits+=1
    hexDigits=significantHexDigits
    if hexDigits>16 or (hexDigits==16 and (not foundFirstNonZero or s[pfxLen+leadingZeroCount+15]>'7')):
        selected='BigInteger'
    elif hexDigits>8 or (hexDigits==8 and (not foundFirstNonZero or s[pfxLen+leadingZeroCount+7]>'7')):
        selected='Long'
    else:
        selected='Integer'
    value=int(s,16)
    expected='Integer' if value<=2**31-1 else ('Long' if value<=2**63-1 else 'BigInteger')
    print(f'{s}: Figure 24 selects {selected}; required type is {expected}; numeric value {value}')
PY"
